/**
 * The style quiz of "ขอทำหนังสือ": each question shows two sample slides (a = left, b = right) that differ in ONE
 * dimension only; the teacher taps the one they prefer, or "ได้ทั้งคู่" (both are fine).
 * The images live in the private bucket under shared/quiz/ and are served by /app/static/quiz/:file
 * (generated by scripts/quiz/render.mjs, uploaded by scripts/seed.mjs).
 */
export type Choice = 'a' | 'b' | 'both';
export const CHOICES: readonly Choice[] = ['a', 'b', 'both'];

export interface Side {
  /** Short Thai label shown under the sample. */
  th: string;
  /** English phrase used in the summary and the brief. */
  en: string;
  /** One line in Thai that says what to look at in the sample. */
  hint: string;
}

export interface Question {
  key: string;
  /** The question, in Thai. */
  q: string;
  /** The dimension's name in English (for the brief). */
  dim: string;
  a: Side;
  b: Side;
  /** Summary text when the teacher picked "both". */
  bothEn: string;
}

