export const QUIZ_LENGTH = QUIZ.length;

/** The order of the summary, most important for the build first (style, colour, visuals, animation, ...). */
const SUMMARY_ORDER = ['style', 'colour', 'visuals', 'animation', 'density', 'interaction', 'language', 'font', 'charts', 'background'];

export function question(n: number): Question | undefined {
  return Number.isInteger(n) && n >= 1 && n <= QUIZ.length ? QUIZ[n - 1] : undefined;
}

/** Public image path of one side of a question; `small` is the 480 px thumbnail. */
export function imagePath(key: string, side: 'a' | 'b', small = false): string {
  return `/app/static/quiz/${key}-${side}${small ? '-sm' : ''}.webp`;
}

/** Every image file name the quiz uses (the static route accepts only these). */
export const QUIZ_FILES: ReadonlySet<string> = new Set(
  QUIZ.flatMap((q) => (['a', 'b'] as const).flatMap((s) => [`${q.key}-${s}.webp`, `${q.key}-${s}-sm.webp`])),
);

export type Answers = Partial<Record<string, Choice>>;

/** 1-based number of the first question without an answer, or 0 when all are answered. */
export function firstUnanswered(answers: Answers): number {
  const i = QUIZ.findIndex((q) => !answers[q.key]);
  return i < 0 ? 0 : i + 1;
}

/** English phrase for one answer, e.g. "vivid colours" or (for "both") "vivid or calm colours". */
export function answerEn(q: Question, c: Choice): string {
  return c === 'both' ? q.bothEn : q[c].en;
}

/** Thai label for one answer, shown to the teacher. */
export function answerTh(q: Question, c: Choice): string {
  return c === 'both' ? `${q.a.th} หรือ ${q.b.th} ก็ได้` : q[c].th;
}

/**
 * The one-line style summary kept with the request, e.g.
 * "Style A modern clean · vivid colours · illustrations · rich animation · one idea per slide · many interactive tasks · Thai · rounded font".
 * Unanswered questions are left out.
 */
export function buildSummary(answers: Answers): string {
  return SUMMARY_ORDER
    .map((k) => QUIZ.find((q) => q.key === k)!)
    .filter((q) => answers[q.key])
    .map((q) => answerEn(q, answers[q.key]!))
    .join(' · ');
}

export interface BriefInput {
  id: number;
  subject: string;
  grade: string;
  textbook: string;
  units: string;
  start_date: string;
  note: string;
  school: string;
  summary: string;
  submitted_at: number | null;
  created_at: number;
}

/**
 * A clean text brief the owner can paste to Claude to order the build. It holds what the build needs and no
 * personal data beyond the school (the teacher's name and LINE id stay in the admin page).
 */
export function buildBrief(r: BriefInput, answers: Answers): string {
  const day = new Date((r.submitted_at ?? r.created_at) * 1000).toISOString().slice(0, 10);
  const lines = [
    `KruSlide book request #${r.id} (${day})`,
    '',
    'Please build interactive lesson slides for this textbook, to the KruSlide standard.',
    '',
    `Subject: ${r.subject}`,
    `Grade: ${r.grade}`,
    `Textbook / publisher: ${r.textbook}`,
    `Units or chapters needed: ${r.units}`,
    `Wanted from: ${r.start_date}`,
    `School: ${r.school || '-'}`,
    `Teacher's note: ${r.note || '-'}`,
    '',
    `Style summary: ${r.summary || buildSummary(answers) || '(quiz not finished)'}`,
    '',
    'Style quiz answers (the teacher chose between two sample slides each time):',
    ...QUIZ.map((q) => {
      const c = answers[q.key];
      if (!c) return `- ${q.dim}: (no answer)`;
      if (c === 'both') return `- ${q.dim}: either is fine (${q.a.en} / ${q.b.en})`;
      const other = c === 'a' ? q.b : q.a;
      return `- ${q.dim}: ${q[c].en} (rather than ${other.en})`;
    }),
    '',
    'Every unit includes: animation on every slide; students answering on the screen; a teacher guide; answers with worked steps.',
    'Fonts: self-hosted Anuphan (Thai) and Inter. No dark neon glow, no gradient text, no serif italics (the "AI look").',
  ];
  return lines.join('\n');
}
